const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs');
(async()=>{fs.mkdirSync('evidence',{recursive:true});let b=await chromium.launch(),errors=[];
for(let width of [320,390,1280]){let p=await b.newPage({viewport:{width,height:844},isMobile:width<500,hasTouch:width<500});p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=400&&!r.url().includes('favicon'))errors.push(r.status()+' '+r.url())});p.on('dialog',d=>d.accept());await p.goto('http://127.0.0.1:8765/wingspan/',{waitUntil:'networkidle'});await p.waitForFunction(()=>DB?.birds.length===707);
assert.match(await p.locator('#advice h2').innerText(),/Уточни/);
await p.evaluate(()=>{S.stockKnown=true;S.roundKnown=true;S.r=2;S.t=0;S.stock.seed=1;S.stock.worm=1;S.stock.eggs=1;renderAll()});
assert.equal(await p.evaluate(()=>projectGame().steps.length),11);
await p.locator('#forecastPanel summary').click();assert.equal(await p.locator('#forecast li').count(),11);
await p.screenshot({path:'evidence/home-'+width+'.png',fullPage:true});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'home overflow '+width);
await p.evaluate(()=>startGuided({kind:'play',candidate:'coot',hab:'water'}));
await p.getByRole('button',{name:'Птица выложена · списать стоимость'}).click();assert.equal(await p.evaluate(()=>S.stock.eggs),0);
await p.reload({waitUntil:'networkidle'});await p.getByRole('button',{name:'Продолжить →'}).click();await p.getByRole('button',{name:'Отменить действие'}).click();assert.equal(await p.evaluate(()=>S.stock.eggs),1);assert.equal(await p.evaluate(()=>held().some(x=>x.id==='coot')),true);
await p.evaluate(()=>startGuided({kind:'draw'}));await p.getByRole('button',{name:'Карты получены',exact:true}).click();assert.match(await p.locator('#actionBody').innerText(),/Ruddy Duck/);
await p.getByRole('button',{name:'Пропустить способность',exact:true}).click();await p.getByRole('button',{name:'Подтвердить ход',exact:true}).click();assert.equal(await p.evaluate(()=>S.t),1);assert.match(await p.locator('#advice h2').innerText(),/Ход соперника/);
await p.locator('details').filter({has:p.locator('#tray')}).locator('summary').click();await p.locator('#tray .tray-slot').first().getByRole('button').click();await p.locator('#dbQuery').fill('Common Raven');await p.waitForFunction(()=>document.querySelectorAll('#dbList .dbrow').length===1);await p.getByRole('button',{name:'Set open card'}).click();assert.equal(await p.evaluate(()=>trayBirds()[0].name),'Common Raven');
await p.locator('.nav [data-tab="birds"]').click();await p.locator('details').filter({has:p.locator('#comboResults')}).locator('summary').click();await p.locator('#findCombos').click();assert.equal(await p.locator('#comboResults .analysis-row').count(),6);
await p.locator('.nav [data-tab="catalog"]').click();await p.locator('#dbQuery').fill('');await p.locator('[data-view="cards"]').click();assert.ok(await p.locator('.fit-rating').count());assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'catalog overflow '+width);
if(width===390)await p.screenshot({path:'evidence/catalog.png',fullPage:true});
await p.evaluate(()=>{S=fresh(false);S.selectedGoals=['Bird Feeder','Nest Box Builder'];S.birds=DB.birds.slice(0,5).map(x=>({...x,id:'setup-'+x.id,loc:'hand'}));S.tab='game';renderAll()});assert.equal(await p.locator('#applySetup').isEnabled(),true);await p.locator('#applySetup').click();assert.equal(await p.evaluate(()=>S.setupMode),false);assert.equal(await p.evaluate(()=>held().length+['worm','seed','fruit','fish','rodent'].reduce((n,k)=>n+S.stock[k],0)),5);
await p.close()}await b.close();assert.deepEqual(errors,[]);console.log('STUDIO PASS: 320,390,1280; forecast, resume/cancel, activation, tray, combination search, setup')})().catch(e=>{console.error(e);process.exitCode=1});
